{
  "application": "data-visualization",
  "case_id": "case-ai-evolution-timeline",
  "language": "en",

  "style": {
    "theme": "editorial",
    "audience": "general public",
    "tone": "engaging, data-dense"
  },

  "goal": [
    {
      "id": "three-track-layout",
      "insight": "Show 3 parallel tracks (Research / Industry / Regulation) across 2010-2025 as a multi-track timeline"
    },
    {
      "id": "lag-pattern",
      "insight": "Research leads industry by 2-4 years, regulation lags industry by 3-5 years: Transformer (2017) to ChatGPT (2022) = 5.4yr, ChatGPT to EU AI Act (2024) = 1.3yr"
    },
    {
      "id": "chatgpt-inflection",
      "insight": "ChatGPT (Nov 2022) compressed the multi-year lag to months — within 14 months: Biden EO, EU AI Act agreement, Bletchley Declaration all happened"
    },
    {
      "id": "density-acceleration",
      "insight": "More milestone events in 2023-2024 across all 3 tracks than in the entire 2010-2017 period"
    },
    {
      "id": "investment-overlay",
      "insight": "Overlay AI investment data: doubled from $48B (2022) to $96B (2024) in the 2 years following ChatGPT"
    }
  ]
}

